python3 << 'EOF'
import fitz, numpy as np
doc = fitz.open('eprint/figures/photonDecay.pdf')
p = doc[0]
dr = p.get_drawings()
# major ticks bottom and left
segs=[]
for d in dr:
    if d.get('width')==0.5 and d.get('color')==(0.0,0.0,0.0):
        for it in d['items']:
            if it[0]=='l':
                a,b=it[1],it[2]; segs.append((a.x,a.y,b.x,b.y))
bt = sorted(round(s[0],2) for s in segs if abs(s[0]-s[2])<0.01 and 3<abs(s[1]-s[3])<5 and max(s[1],s[3])>200)
lt = sorted(round(s[1],2) for s in segs if abs(s[1]-s[3])<0.01 and 3<abs(s[0]-s[2])<5 and min(s[0],s[2])<80)
print('bottom major x:', bt)
print('left major y:', lt)
# labels
for b in p.get_text('dict')['blocks']:
    for l in b.get('lines', []):
        txt=''.join(s['text'] for s in l['spans'])
        if '10' in txt or txt.strip().isdigit():
            print(repr(txt), [round(v,1) for v in l['bbox']])
# black solid curves
for i,d in enumerate(dr):
    if d.get('width') and abs(d['width']-1.6)<0.01 and d.get('dashes')=='[] 0' and d.get('color')==(0.0,0.0,0.0):
        pts=[]
        for it in d['items']:
            if it[0]=='l':
                if not pts: pts.append((it[1].x,it[1].y))
                pts.append((it[2].x,it[2].y))
        pts=np.array(pts)
        print('black solid drawing', i, pts.shape, 'x', pts[:,0].min(), pts[:,0].max())
        np.save(f'/tmp/pd_{i}.npy', pts)
